<template>
  <div class="forgot-password-page">
    <el-card class="forgot-password-card" shadow="always">
      <template #header>
        <div class="page-header">
          <h1>忘记密码</h1>
          <p>输入用户名或邮箱，我们将发送重置邮件</p>
        </div>
      </template>

      <el-form :model="form" :rules="rules" ref="formRef" @keyup.enter="handleSubmit">
        <el-form-item prop="username">
          <el-input
            v-model="form.username"
            placeholder="用户名或邮箱"
            :prefix-icon="User"
            size="large"
          />
        </el-form-item>
        <el-form-item>
          <el-button
            type="primary"
            size="large"
            :loading="loading"
            @click="handleSubmit"
            style="width: 100%"
          >
            发送重置邮件
          </el-button>
        </el-form-item>
      </el-form>

      <div class="actions">
        <router-link to="/login">返回登录</router-link>
      </div>

      <el-alert
        v-if="successMessage"
        :title="successMessage"
        type="success"
        show-icon
        :closable="false"
        class="success-alert"
      />
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { reactive, ref } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
import { User } from '@element-plus/icons-vue'
import { requestPasswordReset } from '@/api/auth'
import { showError } from '@/utils/error'

const form = reactive({
  username: '',
})

const loading = ref(false)
const successMessage = ref('')
const formRef = ref<FormInstance>()

const rules: FormRules = {
  username: [{ required: true, message: '请输入用户名或邮箱', trigger: 'blur' }],
}

async function handleSubmit() {
  if (!formRef.value) return

  try {
    await formRef.value.validate()
  } catch {
    return
  }

  loading.value = true
  successMessage.value = ''

  try {
    const response = await requestPasswordReset(form.username)
    successMessage.value = response.message
    form.username = ''
  } catch (error) {
    showError(error, '请求失败，请稍后重试')
  } finally {
    loading.value = false
  }
}
</script>

